namespace OpenTPW;

/// <summary>
/// The queue slice's approximation register (docs/GUESTS.md, "Queues"; docs/reverse/QUEUE-plan.md §10). Each
/// entry is tagged <c>[APPROX:QUEUE-NNN]</c> at its code site. Everything else in the queue model is traced
/// from the Mac binary (BIN labels at the code sites).
/// </summary>
public static class QueueApproximations
{
	public static readonly IReadOnlyList<(string Id, string Rule)> Entries = new[]
	{
		("QUEUE-003", "back-cell admission and fourth-slot path geometry are implemented; supported live typed HasQueue entries derive their front from the actual entry link byte (+0x0C, tp.exe 0x4DE040, bits 1, 16, 64, 4), and a native zero front (no cardinal bit; 0x4DE4A0 reads such a ride as unconnected, which the opening guard still answers permissively under ECON-049) leaves its demolition without a count to undo (0x527FB4) and its re-evaluation without a block stamp; a zero-front ride has back cell 0 and size 0 for the guests (they neither score, choose nor join it, and its queued guests but the called one leave at the re-evaluation) with the host's one-cell geometry kept for the called guest's stand cell and the queue tool; unsupported entries (a neighbour off the map) and untyped worlds retain the host positive one-cell fallback; divergent imported mEntryPos and the native cache invalidation timing (0x4DE130 keeps +0x3A until the next 0x4DE1F0, where OpenTPW recomputes on every grid change) remain unsupported"),
		("QUEUE-010", "a guest leaving a queue (0x5004AA, the queue edit's dismissal 0x501390, a removed ride's message 0x4FB360) stays where it stands in state 6 on every placed ride, whatever its cell is now (a path, a queue cell, the owned stand cell, or a cell the queue's undo or a demolition emptied), and decides from there by the ported wander (0x4F9490); a bridge without placed cells (no owner word or no exit cell: the gates, the test rigs, the Theme Park Inc slice) and the exits of a guest whose attraction is gone retain the front/nearest-path relocation, whose cells carry no links to walk off by"),
		("QUEUE-012", "queue cells follow the decision order of tp.exe's validator 0x00535670 (QueueCellValidator, replayed on the executable's own answers): the flag 0x40 refuses first, an object's cell (types 4, 9 and 10) is accepted only when the owner's overwrite priority is below the tool's 3 (0x818C10, 0x535D66; Objects.GivesWay), a hoarding post and the three cells beside it are refused on owned land as well (by the queue and the path tool), a corner or junction track tile and the coaster marker 0x15 are refused, an empty cell is accepted and the validator reads no MAP terrain bit; OpenTPW's per-cell route still takes the terrain rule of the map start's cell types (Objects.Grid.CheckTerrain, with the Easymode save's occupied cells before the live map is attached), refuses any non-empty cell, so it neither lets a queue run over its own queue cell (the original: owner = the ride's cell, not two links) nor over a straight or stub track tile, and keeps no latch across a drag (the line walker stops at the first refusal); the placed rides' lines replace path cells in QueueSegmentReducer; not determined: the owner priority 0x818C14 the validator keeps when no class-3 thing is found, and whether the latches 0x816D50 and 0x816D58 reset between drags"),
		("QUEUE-015", "the queue tool's undo (Back 0x52FE50) takes cells and refunds as 0x5367A0 does and writes no guest: the re-evaluation that follows (0x4DE1F0 at 0x52FFEC, 0x501390 per guest) dismisses by place alone; the corner walk's counters (+0x20: 1 on a corner, 0 elsewhere, 0x5302C2) are written by the queue edit click, whose tool takes the segments back through the native undo (the cells go from the segment's end, so a corner keeps its counter 1 - 1 and stays); a ride whose front holds no queue cell is demolished with one cell's debit (0x527FB4). The tool entries that run no walk here (a ride's placement, the ride window's button, a track's or coaster's completion) take the chain from the segment's first cell on without counters, and the removal from a clicked cell on stays only as the labelled extensions EXT:dev-one-click-remove and EXT:queue-backtrack, which keep the original's guest policy (the clear writes no guest and the re-evaluation dismisses by place)"),
	};
}
